"""인증 — 토큰 하나로 관제 대시보드·체험·조작 서버·커넥톰 연산 서버를 지킨다.

KISA 개발보안 가이드: 구현 2-1(인증 없는 중요 기능), 2-2(부적절한 인가), 2-9(취약한 비밀번호), 2-12(주소에 남는 중요정보),
설계 SR2-1(인증 대상 및 방식)·SR2-3(비밀번호 관리).

- **토큰 하나**: `REFLEXGUARD_TOKEN`(예전 이름 `REFLEXGUARD_DASHBOARD_TOKEN`도 받음). 없으면 처음 켠 서버가 만들어
  `logs/token`(이 계정만 읽기, 0600)에 두고, 같은 PC의 다른 서버·로봇은 그 파일을 읽는다 → 따로 설정하지 않아도 켜져 있다.
  다른 PC의 로봇·서버는 같은 값을 환경 변수로 준다. 약한 값(짧거나 한 종류 문자)은 받지 않는다.
- **두 권한**: 토큰 = 조작(명령·Webots 조작·카메라 체험), 보기 전용 토큰(토큰에서 HMAC으로 만든 짧은 값) = 관제 화면 보기만.
- **브라우저**: 처음 한 번 토큰을 넣어 로그인하면 HttpOnly 쿠키(만료 시각 + HMAC 서명)로 다닌다. 주소의 `?token=`도 받지만
  곧바로 쿠키로 바꾸고 주소에서 지운다. 도구(curl 등)는 `X-Token` 헤더로 보낸다.
"""

from __future__ import annotations

import base64
import hashlib
import hmac
import os
import re
import secrets
import string
import time
from collections.abc import Mapping
from http.cookies import CookieError, SimpleCookie
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
TOKEN_ENV_VARS = ("REFLEXGUARD_TOKEN", "REFLEXGUARD_DASHBOARD_TOKEN")  # 앞의 것이 우선
TOKEN_FILE = ROOT / "logs" / "token"
COOKIE_NAME = "rg_session"
SESSION_S = 12 * 3600          # 로그인 쿠키 유효 시간
CONTROL, VIEW = "control", "view"


class WeakToken(ValueError):
    """토큰이 너무 약하다 (서버가 켜지지 않게 한다)."""


def token_problem(token: str) -> str:
    """토큰이 약하면 그 까닭, 괜찮으면 빈 문자열. KISA 비밀번호 기준: 문자 종류 3가지 이상이면 8자, 2가지면 10자 이상."""
    kinds = sum(any(c in group for c in token) for group in
                (string.ascii_lowercase, string.ascii_uppercase, string.digits))
    kinds += any(not c.isalnum() for c in token)
    if any(c.isspace() for c in token):
        return "공백은 쓸 수 없습니다"
    if kinds >= 3 and len(token) >= 8 or kinds >= 2 and len(token) >= 10:
        return ""
    return "영문 대·소문자·숫자·특수문자 중 3가지 이상이면 8자, 2가지면 10자 이상이어야 합니다"


def rotate_token(path: Path = TOKEN_FILE) -> str:
    """새 토큰으로 바꿔 파일에 쓴다 (임시 파일에 0600으로 쓴 뒤 바꿔 단다). 켜져 있는 서버는 다시 켜야 새 값을 쓰고,
    예전 토큰으로 만든 로그인 쿠키·보기 전용 토큰은 그때부터 모두 무효다 (KISA 설계 SR2-5 암호키 관리 — 교체)."""
    private_dir(path.parent)
    token = new_token()
    partial = path.with_name(path.name + ".new")
    fd = os.open(partial, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as file:
        file.write(token + "\n")
    partial.replace(path)
    return token


def private_dir(path: Path) -> Path:
    """이 계정만 들어갈 수 있는 폴더(0700)로 만든다 — 기록·토큰·인증서가 다른 계정에 읽히지 않게 (KISA 구현 2-3)."""
    path.mkdir(parents=True, exist_ok=True)
    try:
        path.chmod(0o700)
    except OSError:  # 내 것이 아닌 폴더면 그대로 둔다
        pass
    return path


def new_token() -> str:
    while True:  # 생성한 값도 같은 기준을 지키게 (거의 언제나 한 번에 된다)
        token = secrets.token_urlsafe(12)  # 16자, 96비트
        if not token_problem(token):
            return token


def load_token(create: bool = False, path: Path = TOKEN_FILE) -> str:
    """환경 변수 → 토큰 파일 → (create면) 새로 만들어 파일에. 아무것도 없으면 빈 문자열(인증 없음 — 클라이언트 쪽)."""
    for name in TOKEN_ENV_VARS:
        token = os.environ.get(name, "").strip()
        if token:
            problem = token_problem(token)
            if problem:
                raise WeakToken(f"{name}가 약합니다: {problem}")
            return token
    try:
        return path.read_text(encoding="utf-8").strip()
    except FileNotFoundError:
        if not create:
            return ""
    private_dir(path.parent)
    token = new_token()
    try:  # 두 서버가 동시에 켜져도 하나만 만든다
        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
    except FileExistsError:
        return path.read_text(encoding="utf-8").strip()
    with os.fdopen(fd, "w", encoding="utf-8") as file:
        file.write(token + "\n")
    return token


def client_token(path: Path = TOKEN_FILE) -> str:
    """로봇·연산 서버가 접속할 때 실을 토큰: 환경 변수 → 토큰 파일. 강도는 서버가 따진다 (여기서는 막지 않는다)."""
    for name in TOKEN_ENV_VARS:
        token = os.environ.get(name, "").strip()
        if token:
            return token
    try:
        return path.read_text(encoding="utf-8").strip()
    except OSError:
        return ""


def view_token(token: str) -> str:
    """보기 전용 토큰: 조작 토큰에서 만든 12자. 조작 토큰을 아는 사람만 알 수 있고, 거꾸로는 알 수 없다."""
    digest = hmac.new(token.encode(), b"reflexguard:view", hashlib.sha256).digest()
    return base64.urlsafe_b64encode(digest[:9]).decode()


def role_for(token: str, provided: str) -> str | None:
    """넣은 값이 조작 토큰이면 'control', 보기 전용 토큰이면 'view', 아니면 None. 시간차가 드러나지 않게 비교한다."""
    if not token or not provided:
        return None
    if hmac.compare_digest(provided.encode(), token.encode()):
        return CONTROL
    if hmac.compare_digest(provided.encode(), view_token(token).encode()):
        return VIEW
    return None


def _sign(token: str, role: str, expires: int) -> str:
    return hmac.new(token.encode(), f"session:{role}:{expires}".encode(), hashlib.sha256).hexdigest()


def session_cookie(token: str, role: str, secure: bool, now: float | None = None) -> str:
    """Set-Cookie 값: <권한>.<만료 시각>.<서명>. HttpOnly(스크립트가 못 읽음)·SameSite=Strict(다른 사이트 요청엔 안 실림)."""
    expires = int((time.time() if now is None else now) + SESSION_S)
    value = f"{role}.{expires}.{_sign(token, role, expires)}"
    return (f"{COOKIE_NAME}={value}; Path=/; HttpOnly; SameSite=Strict; Max-Age={SESSION_S}"
            + ("; Secure" if secure else ""))


def logout_cookie(secure: bool) -> str:
    return f"{COOKIE_NAME}=; Path=/; HttpOnly; SameSite=Strict; Max-Age=0" + ("; Secure" if secure else "")


def role_from_cookie(token: str, cookie_header: str, now: float | None = None) -> str | None:
    if not token or not cookie_header:
        return None
    try:
        morsel = SimpleCookie(cookie_header).get(COOKIE_NAME)
    except CookieError:
        return None
    if morsel is None:
        return None
    role, _, rest = morsel.value.partition(".")
    expires, _, signature = rest.partition(".")
    if role not in (CONTROL, VIEW) or not expires.isdigit() or int(expires) < (time.time() if now is None else now):
        return None
    return role if hmac.compare_digest(signature, _sign(token, role, int(expires))) else None


def request_role(token: str, headers: Mapping[str, str]) -> str | None:
    """HTTP 요청의 권한: X-Token 헤더(도구) 또는 로그인 쿠키(브라우저). 토큰을 쓰지 않는 서버(빈 토큰)면 언제나 'control'."""
    if not token:
        return CONTROL
    return role_for(token, headers.get("X-Token", "")) or role_from_cookie(token, headers.get("Cookie", ""))


PRELOGIN_COOKIE = "rg_prelogin"
PRELOGIN_S = 600


def _cookie(cookie_header: str, name: str) -> str:
    try:
        morsel = SimpleCookie(cookie_header or "").get(name)
    except CookieError:
        return ""
    return morsel.value if morsel is not None else ""


def csrf_token(token: str, cookie_header: str) -> str:
    """로그인 쿠키에 묶인 CSRF 값 — 화면이 GET /api/me·/api/portal로 받아 상태를 바꾸는 요청의 X-CSRF-Token에 싣는다.
    다른 사이트는 쿠키를 읽을 수 없어 이 값을 만들지 못한다 (SameSite·Origin 확인에 더한 한 겹 — KISA 구현 1-11)."""
    session = _cookie(cookie_header, COOKIE_NAME)
    if not token or not session:
        return ""
    return hmac.new(token.encode(), f"csrf:{session}".encode(), hashlib.sha256).hexdigest()[:32]


_NONCE = re.compile(r"[A-Za-z0-9_-]{16,64}")


def prelogin(token: str, secure: bool, cookie_header: str = "") -> tuple[str, str]:
    """로그인 전 CSRF: (Set-Cookie 값, 로그인 폼의 숨은 칸). 로그인 때 둘이 짝이 맞아야 한다 — 다른 사이트가 사용자를
    공격자 쪽으로 로그인시키는 것(login CSRF)을 막는다.
    브라우저에 이미 로그인 전 쿠키가 있으면 그 값을 다시 쓴다 — 로그인 화면 뒤에 따라온 요청(아이콘·두 번째 탭)이
    쿠키를 새로 바꿔 먼저 띄운 폼이 '오래됨'이 되지 않게. 값은 HttpOnly라 다른 사이트가 읽거나 정하지 못한다."""
    nonce = _cookie(cookie_header, PRELOGIN_COOKIE)
    if not _NONCE.fullmatch(nonce):
        nonce = secrets.token_urlsafe(16)
    field = hmac.new(token.encode(), f"prelogin:{nonce}".encode(), hashlib.sha256).hexdigest()[:32]
    cookie = (f"{PRELOGIN_COOKIE}={nonce}; Path=/; HttpOnly; SameSite=Strict; Max-Age={PRELOGIN_S}"
              + ("; Secure" if secure else ""))
    return cookie, field


def prelogin_ok(token: str, cookie_header: str, field: str) -> bool:
    nonce = _cookie(cookie_header, PRELOGIN_COOKIE)
    if not token or not nonce or not field:
        return False
    expected = hmac.new(token.encode(), f"prelogin:{nonce}".encode(), hashlib.sha256).hexdigest()[:32]
    return hmac.compare_digest(field.encode(), expected.encode())


def safe_next(path: str) -> str:
    """로그인 뒤 돌아갈 주소: 이 서버 안의 경로만 (다른 사이트로 넘기지 않게 — KISA 구현 1-7)."""
    if not path.startswith("/") or path.startswith("//") or "\\" in path or any(ord(c) < 32 for c in path):
        return "/"
    return path


def login_page(title: str, next_path: str, error: str = "", csrf: str = "") -> bytes:
    """토큰을 넣는 작은 화면. 값은 POST /login 본문으로만 보내 주소·방문 기록에 남지 않게 한다."""
    from html import escape
    message = f'<p class="error">{escape(error)}</p>' if error else ""
    return f"""<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>로그인 · {escape(title)}</title>
<link rel="icon" type="image/png" sizes="32x32" data-brand="favicon" href="data:image/png;base64,">
<style>
  :root {{ color-scheme: light dark; --bg: #f4f5f7; --card: #fff; --ink: #1d2330; --muted: #5b6475; --line: #d6dae2; --accent: #2f6fe4; --bad: #c62f2f; }}
  @media (prefers-color-scheme: dark) {{ :root {{ --bg: #12151b; --card: #1b1f27; --ink: #e8ebf1; --muted: #9aa3b5; --line: #2c3240; --accent: #6b9bff; --bad: #ff7a7a; }} }}
  body {{ margin: 0; min-height: 100vh; display: grid; place-items: center; background: var(--bg); color: var(--ink);
         font: 15px/1.5 system-ui, -apple-system, "Segoe UI", "Noto Sans KR", sans-serif; }}
  form {{ background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 24px; width: min(360px, calc(100vw - 32px)); box-sizing: border-box; }}
  h1 {{ font-size: 18px; margin: 0 0 4px; }} p {{ margin: 0 0 16px; color: var(--muted); }}
  input {{ width: 100%; box-sizing: border-box; padding: 10px 12px; border: 1px solid var(--line); border-radius: 8px; background: transparent; color: inherit; font: inherit; }}
  button {{ margin-top: 12px; width: 100%; padding: 10px; border: 0; border-radius: 8px; background: var(--accent); color: #fff; font: inherit; font-weight: 600; }}
  .error {{ color: var(--bad); margin: 12px 0 0; }}
  .logo {{ display: block; margin: 0 0 18px; }} .logo-light {{ display: none; }}
  @media (prefers-color-scheme: light) {{ .logo-light {{ display: block; }} .logo-dark {{ display: none; }} }}
</style></head>
<body><form method="post" action="/login">
  <img class="logo logo-light" data-brand="logo" src="data:image/png;base64," width="200" height="50" alt="ReflexGuard"><img class="logo logo-dark" data-brand="logo-dark" src="data:image/png;base64," width="200" height="50" alt="ReflexGuard">
  <h1>{escape(title)}</h1>
  <p>서버를 켠 터미널에 나온 토큰을 넣으세요 (보기 전용 토큰이면 보기만 됩니다).</p>
  <input name="token" type="password" autocomplete="current-password" autofocus required aria-label="토큰">
  <input type="hidden" name="next" value="{escape(safe_next(next_path))}">
  <input type="hidden" name="csrf" value="{escape(csrf)}">
  <button type="submit">들어가기</button>{message}
</form></body></html>""".encode()


def main(argv: list[str] | None = None) -> None:
    """python -m common.auth [--create | --rotate] — 이 PC의 토큰과 보기 전용 토큰을 보여 준다 (터미널에만, 기록 파일에는
    남기지 않는다). --create면 없을 때 만든다 (실행 스크립트가 서버를 켜기 전에 부른다). --rotate면 새 토큰으로 바꾼다."""
    import sys
    args = sys.argv[1:] if argv is None else argv
    if "--rotate" in args:
        named = [name for name in TOKEN_ENV_VARS if os.environ.get(name, "").strip()]
        if named:
            raise SystemExit(f"토큰을 환경 변수({named[0]})로 주고 있습니다 — 그 값을 바꾸세요 (파일은 쓰지 않음).")
        token = rotate_token()
        print("토큰을 바꿨습니다. 관제·연산·체험 서버를 다시 켜면 새 값을 씁니다 (예전 로그인·보기 전용 토큰은 무효).")
        print(f"조작 토큰:      {token}")
        print(f"보기 전용 토큰: {view_token(token)}")
        print("다른 PC의 로봇·서버에는 REFLEXGUARD_TOKEN을 새 값으로 바꿔 주세요.")
        return
    try:
        token = load_token(create="--create" in args)
    except WeakToken as error:
        raise SystemExit(str(error)) from error
    if not token:
        print("아직 토큰이 없습니다 — 관제·연산·체험 서버 중 하나를 켜면 logs/token에 만들어집니다.")
        return
    print(f"조작 토큰:      {token}")
    print(f"보기 전용 토큰: {view_token(token)}")


if __name__ == "__main__":
    main()
